import 'package:flutter/material.dart';class IncidentStatusBadge extends StatelessWidget{const IncidentStatusBadge({super.key,required this.status});final String status;@override Widget build(BuildContext context){final c=switch(status){'Resolved'=>Colors.green,'In Progress'=>Colors.blue,'Under Review'=>Colors.orange,_=>Colors.grey};return Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:5),decoration:BoxDecoration(color:c.withValues(alpha:.12),borderRadius:BorderRadius.circular(20)),child:Text(status,style:TextStyle(color:c,fontSize:12,fontWeight:FontWeight.w600)));}}
